WITH valid AS (SELECT id, full_name, dept_id, hire_date, is_remote, level, CASE WHEN level = 'L4' THEN 1 ELSE 0 END is_l4 FROM employees WHERE hire_date >= DATE '2023-07-23' AND manager_id IS NOT NULL) SELECT d.dept_name, e.level, COUNT(*) AS cnt, ROUND(SUM(e.is_l4), 2) AS total_is_l4 FROM valid e INNER JOIN departments d ON e.dept_id = d.id GROUP BY GROUPING SETS ((d.dept_name, e.level), (d.dept_name), ());
